messageHandlers.script:
	try:
		provider = self.view.custom.provider.strip('[]')
	except:
		return
	UDTPath = self.view.custom.selectedUDTType
	firstInstance = self.view.custom.firstInstance
	writeTags = self.view.custom.writeTags
	try:
		splitPath = UDTPath.split("]",1)[1]
	except:
		splitPath = UDTPath
	if splitPath == None:
		return
#	self.view.custom.test = splitPath
	#self.getChild('FlexContainer').getChild('FlexContainer_0').getChild('Label').props.text = splitPath
#	self.getChild('debug').props.params.text = splitPath
	query = {
	  "options": {
	    "includeUdtMembers": True,
	    "includeUdtDefinitions": True
	  },
	  "condition": {
	    "hierarchy": {
	      "typeId": UDTPath,
	      "relationship": "SubType"
	    },
	    "tagType": "AtomicTag",
	    "attributes": {
	      "values": [],
	      "requireAll": True
	    },
	    "valueSource": [
	      "opc",
	      "memory"
	    ]
	  },
	  "returnProperties": [
	    "tagType"
	  ]
	}

	results = system.tag.query(provider, query)
	self.view.custom.test = firstInstance
	tagList = []
	for result in results:
		if str(firstInstance) not in str(result['fullPath']):
			continue
		oList = {}

		tagPart = '{...}'+str(result['fullPath']).replace(firstInstance,"")
#		if '/Config' in tagPart:
#			continue
#		elif tagPart == '{...}':
#			continue

		oList["label"] = tagPart
		oList["newValue"] = ''
		oList["tagType"] = result['tagType']
		try:
			oList["valueSource"] = result['valueSource']
		except:
			oList["valueSource"] = ''
		try:
			oList["oldValue"] = result['value']
		except:
			oList["oldValue"] = 0

		tagList.append(oList)

		newStageTags = []
		for eachStage in writeTags:
			newList = {}
			if str(eachStage['label']) == tagPart:
				try:
					newList["oldValue"] = result['value']
				except:
					newList["oldValue"] = 0
			else:
				newList["oldValue"] = eachStage['oldValue']

			newList["label"] = eachStage['label']
			newList["newValue"] = eachStage['newValue']
			newList["tagType"] = eachStage['tagType']
			newList["valueSource"] = eachStage['valueSource']

			newStageTags.append(newList)
		writeTags = newStageTags

	sortedTags = sorted(tagList,key=lambda k: k.get('value'))
	self.view.custom.tagList = sortedTags
	self.view.custom.writeTags = writeTags

	self.view.custom.UDTTags = results
	system.perspective.sendMessage('updateTagFilter')

