#	limit = 100

	query = {
	  "options": {
	    "includeUdtMembers": False,
	    "includeUdtDefinitions": False
	  },
	  "condition": {
	    "hierarchy": {
	      "typeId": selectedUDTType,
	      "relationship": "SubType"
	    },
	    "tagType": "UdtInstance",
	    "attributes": {
	      "values": [],
	      "requireAll": True
	    }
	  },
	  "returnProperties": [
		"tagType",
	    "quality"
	  ]
	}

	# Limited to 100 rows. Use continuationPoint functionality to continue from last result, 
	# or remove limit for full results.
	results = system.tag.query(provider, query)

	instanceList = []
	for result in results:
		oList = {}

		oList["label"] = result['fullPath']
		oList["selected"] = True

		instanceList.append(oList)

	sortedTags = sorted(instanceList,key=lambda k: k.get('label'))
	self.view.custom.allUDTInstances = sortedTags
	try:
		self.view.custom.firstInstance = sortedTags[0]['label']
